function bgd_showSection(id, btn) {
  document.querySelectorAll('#page-giadat .section').forEach(s => s.classList.remove('active'));
  const el = document.getElementById(id);
  if(el) el.classList.add('active');
  document.querySelectorAll('.bgd-snav-btn').forEach(b => b.classList.remove('active'));
  if(btn) btn.classList.add('active');
  if(id === 'loi-du-lieu') { try { bgd_renderAudit(); } catch(e) { console.error('[HM-11]', e); } }
}

// ===== KH CALCULATOR =====
function kh_getCoeff(area, loai) {
  if(!area || area <= 0) return { val:1, label: loai==='nn'?'K3':'K2', note:'1,00 (mặc định – chưa nhập DT)' };
  if(loai === 'nn') {
    if(area < 200)   return {val:1,    label:'K3', note:'K3.1 – DT<200m²'};
    if(area < 500)   return {val:0.95, label:'K3', note:'K3.2 – 200–500m²'};
    if(area < 2000)  return {val:0.9,  label:'K3', note:'K3.3 – 500–2.000m²'};
    if(area < 5000)  return {val:0.8,  label:'K3', note:'K3.4 – 2.000–5.000m²'};
    if(area < 10000) return {val:0.7,  label:'K3', note:'K3.5 – 5.000–10.000m²'};
    return                  {val:0.5,  label:'K3', note:'K3.6 – DT≥10.000m²'};
  }
  if(area < 100)  return {val:1,   label:'K2', note:'DT<100m²'};
  if(area < 300)  return {val:0.9, label:'K2', note:'100–300m²'};
  if(area < 500)  return {val:0.8, label:'K2', note:'300–500m²'};
  if(area < 1000) return {val:0.7, label:'K2', note:'500–1.000m²'};
  return               {val:0.5, label:'K2', note:'DT≥1.000m²'};
}

function kh_liveCalc() {
  const dongia = parseFloat(document.getElementById('kh-dongia').value) || 0;
  const loai   = document.getElementById('kh-loaidat').value;
  const area   = parseFloat(document.getElementById('kh-dientich').value) || 0;
  const cf     = kh_getCoeff(area, loai);
  // update K23 badge
  const badge  = document.getElementById('kh-k23-badge');
  if(badge) {
    badge.textContent = cf.label + ' = ' + cf.val.toFixed(2) + '  ·  ' + cf.note;
    badge.style.background = cf.val < 1 ? '#fde8e6' : (cf.val === 1 ? '#dbeafe' : '#d5f5e3');
    badge.style.color      = cf.val < 1 ? '#c0392b' : (cf.val === 1 ? '#1d4ed8' : '#1a7a30');
  }
  const k1 = parseFloat(document.getElementById('kh-k1').value);
  const k4 = parseFloat(document.getElementById('kh-k4').value);
  const k5 = parseFloat(document.getElementById('kh-k5').value);
  const h1 = parseFloat(document.getElementById('kh-h1').value);
  const h2 = parseFloat(document.getElementById('kh-h2').value);
  const hs = k1 * cf.val * k4 * k5 * h1 * h2;
  const hsEl = document.getElementById('kh-preview-hs');
  const valEl = document.getElementById('kh-preview-val');
  if(hsEl) hsEl.textContent = hs.toFixed(4);
  if(valEl) {
    valEl.textContent = dongia > 0
      ? Math.round(dongia * hs).toLocaleString('vi-VN') + ' đ/m²'
      : '— (chưa nhập đơn giá)';
  }
}

function kh_tinhGia() {
  const dongia = parseFloat(document.getElementById('kh-dongia').value) || 0;
  if(dongia <= 0) { alert('Vui lòng nhập đơn giá lựa chọn từ bảng!'); return; }
  const loai = document.getElementById('kh-loaidat').value;
  const area = parseFloat(document.getElementById('kh-dientich').value) || 0;
  const cf   = kh_getCoeff(area, loai);
  const k1   = parseFloat(document.getElementById('kh-k1').value);
  const k4   = parseFloat(document.getElementById('kh-k4').value);
  const k5   = parseFloat(document.getElementById('kh-k5').value);
  const h1   = parseFloat(document.getElementById('kh-h1').value);
  const h2   = parseFloat(document.getElementById('kh-h2').value);
  const tongHS = k1 * cf.val * k4 * k5 * h1 * h2;
  const tong   = dongia * tongHS;
  const areaStr = area > 0 ? ' (' + area.toLocaleString('vi-VN') + ' m²)' : '';

  const rv = document.getElementById('kh-result-value');
  if(rv) rv.textContent = Math.round(tong).toLocaleString('vi-VN', {maximumFractionDigits:0});

  const items = [
    ['Đơn giá tra bảng', dongia.toLocaleString('vi-VN') + ' đ', false],
    ['K1 – Mặt tiếp giáp', k1.toFixed(2), k1 > 1],
    [cf.label + ' – DT' + areaStr, cf.val.toFixed(2), cf.val !== 1],
    ['K4 – Mặt tiền chính', k4.toFixed(2), k4 !== 1],
    ['K5 – Hình dáng', k5.toFixed(2), k5 !== 1],
    ['H1 – Lợi thế', h1.toFixed(2), h1 > 1],
    ['H2 – Bất lợi', h2.toFixed(2), h2 < 1],
    ['Tổng hệ số K×H', tongHS.toFixed(4), true],
  ];
  const bkEl = document.getElementById('kh-breakdown');
  if(bkEl) bkEl.innerHTML = items.map(function(item) {
    return '<div class="kh-bd-item"><div class="kh-bd-label">' + item[0] + '</div>'
         + '<div class="kh-bd-val' + (item[2] ? ' hi' : '') + '">' + item[1] + '</div></div>';
  }).join('');

  const box = document.getElementById('kh-result');
  if(box) {
    box.classList.add('show');
    try { box.scrollIntoView({behavior:'smooth', block:'nearest'}); } catch(e) {}
  }
}

function kh_reset() {
  const ids = ['kh-dongia','kh-dientich'];
  ids.forEach(function(id) { const el = document.getElementById(id); if(el) el.value=''; });
  const sels = ['kh-loaidat','kh-k1','kh-k5','kh-h1','kh-h2'];
  sels.forEach(function(id) { const el = document.getElementById(id); if(el) el.selectedIndex=0; });
  const k4el = document.getElementById('kh-k4'); if(k4el) k4el.selectedIndex=1;
  const box  = document.getElementById('kh-result'); if(box) box.classList.remove('show');
  kh_liveCalc();
}

