/* Thực thi xóa sau khi user xác nhận */
function archiveConfirmDelete() {
  const isData = (_archiveDeleteTargetType === 'data');
  const list   = isData ? _archiveDataList : _archiveReportList;

  // Thu thập IDB keys trước khi xóa
  const idbKeysToDelete = [];
  if (!isData) {
    // Report: xóa rpt_ keys
    if (_archiveDeleteMode === 'one' && list[_archiveDeleteIdx]) {
      idbKeysToDelete.push(_idbKey(list[_archiveDeleteIdx]));
    } else if (_archiveDeleteMode === 'selected') {
      _archiveDeleteIdx.forEach(i => { if (list[i]) idbKeysToDelete.push(_idbKey(list[i])); });
    } else if (_archiveDeleteMode === 'all') {
      list.forEach(item => idbKeysToDelete.push(_idbKey(item)));
    }
  } else {
    // Data: xóa dat_ keys — FIX: trước đây bị bỏ qua, gây orphan data tồn đọng trong IDB
    if (_archiveDeleteMode === 'one' && list[_archiveDeleteIdx]) {
      idbKeysToDelete.push(_idbDataKey(list[_archiveDeleteIdx]));
    } else if (_archiveDeleteMode === 'selected') {
      _archiveDeleteIdx.forEach(i => { if (list[i]) idbKeysToDelete.push(_idbDataKey(list[i])); });
    } else if (_archiveDeleteMode === 'all') {
      list.forEach(item => idbKeysToDelete.push(_idbDataKey(item)));
    }
  }

  if (_archiveDeleteMode === 'one') {
    list.splice(_archiveDeleteIdx, 1);
    showToast('🗑️ Đã xóa bản lưu trữ', 'green');
  } else if (_archiveDeleteMode === 'selected') {
    const sorted = [..._archiveDeleteIdx].sort((a, b) => b - a);
    sorted.forEach(i => list.splice(i, 1));
    showToast(`🗑️ Đã xóa ${sorted.length} bản lưu trữ`, 'green');
  } else if (_archiveDeleteMode === 'all') {
    if (isData) { _archiveDataList = []; showToast('🗑️ Đã xóa toàn bộ lưu trữ dữ liệu', 'green'); }
    else        { _archiveReportList = []; window._archiveReportList = _archiveReportList; showToast('🗑️ Đã xóa toàn bộ lưu trữ báo cáo', 'green'); }
  }

  // Xóa reportData khỏi IDB (fire-and-forget)
  idbKeysToDelete.forEach(k => _archIdbDelete(k).catch(() => {}));

  archiveSaveToStorage();
  if (isData) archiveRenderDataList(); else archiveRenderReportList();
  closeArchiveDeleteModal();
}

function closeArchiveDeleteModal() {
  document.getElementById('modal-archive-delete').style.display = 'none';
  _archiveDeleteMode = null;
  _archiveDeleteIdx  = null;
}

// Storage persistence
/* ═══════════════════════════════════════════════════════════════
   💾 IndexedDB WRAPPER — Lưu trữ reportData bền vững
   Thay thế sessionStorage (chỉ tồn tại trong 1 phiên tab).
   IndexedDB tồn tại qua cả khi đóng/mở lại trình duyệt.
   ═══════════════════════════════════════════════════════════════ */
const _IDB_NAME    = 'TWIN_Archive_v1';
const _IDB_STORE   = 'reportData';
const _IDB_VERSION = 1;

function _idbOpen() {
  return new Promise((resolve, reject) => {
    if (!window.indexedDB) { reject(new Error('IndexedDB not supported')); return; }
    const req = indexedDB.open(_IDB_NAME, _IDB_VERSION);
    req.onupgradeneeded = e => {
      const db = e.target.result;
      if (!db.objectStoreNames.contains(_IDB_STORE)) {
        db.createObjectStore(_IDB_STORE); // key = external string key
      }
    };
    req.onsuccess  = e => resolve(e.target.result);
    req.onerror    = e => reject(e.target.error);
    req.onblocked  = () => reject(new Error('IDB blocked'));
  });
}

function _archIdbPut(key, value) {
  return _idbOpen().then(db => new Promise((resolve, reject) => {
    const tx  = db.transaction(_IDB_STORE, 'readwrite');
    const req = tx.objectStore(_IDB_STORE).put(value, key);
    req.onsuccess = () => { db.close(); resolve(); };
    req.onerror   = e  => { db.close(); reject(e.target.error); };
  }));
}

function _archIdbGet(key) {
  return _idbOpen().then(db => new Promise((resolve, reject) => {
    const tx  = db.transaction(_IDB_STORE, 'readonly');
    const req = tx.objectStore(_IDB_STORE).get(key);
    req.onsuccess = e  => { db.close(); resolve(e.target.result); };
    req.onerror   = e  => { db.close(); reject(e.target.error); };
  }));
}

function _archIdbDelete(key) {
  return _idbOpen().then(db => new Promise((resolve, reject) => {
    const tx  = db.transaction(_IDB_STORE, 'readwrite');
    const req = tx.objectStore(_IDB_STORE).delete(key);
    req.onsuccess = () => { db.close(); resolve(); };
    req.onerror   = e  => { db.close(); reject(e.target.error); };
  }));
}

function _archIdbGetAllKeys() {
  return _idbOpen().then(db => new Promise((resolve, reject) => {
    const tx  = db.transaction(_IDB_STORE, 'readonly');
    const req = tx.objectStore(_IDB_STORE).getAllKeys();
    req.onsuccess = e  => { db.close(); resolve(e.target.result || []); };
    req.onerror   = e  => { db.close(); reject(e.target.error); };
  }));
}

/* Tạo key ổn định cho 1 snapshot dựa trên timestamp lúc lưu */
function _idbKey(item)     { return `rpt_${item.timestamp || item.name}`; }
function _idbDataKey(item) { return `dat_${item.timestamp || item.name}`; }

/* Lưu item.data của TẤT CẢ data-archive vào IDB */
async function idbSaveAllDataItems() {
  const validKeys = new Set();
  for (const item of _archiveDataList) {
    const k = _idbDataKey(item);
    validKeys.add(k);
    if (item.data) {
      try { await _archIdbPut(k, item.data); } catch(e) { console.warn('[IDB] dat put:', e); }
    }
  }
  // Dọn orphan keys dat_*
  try {
    const allKeys = await _archIdbGetAllKeys();
    for (const k of allKeys) {
      if (k.startsWith('dat_') && !validKeys.has(k)) await _archIdbDelete(k).catch(()=>{});
    }
  } catch(e) {}
}

/* Khôi phục item.data từ IDB vào _archiveDataList */
async function idbRestoreAllDataItems() {
  let restored = 0;
  for (const item of _archiveDataList) {
    if (item.data && typeof item.data === 'object') continue;
    try {
      const d = await _archIdbGet(_idbDataKey(item));
      if (d && typeof d === 'object') { item.data = d; restored++; }
    } catch(e) {}
  }
  if (restored > 0) {
    (0)&&console.log(`[IDB] ✅ Khôi phục data cho ${restored}/${_archiveDataList.length} data-archive`);
    archiveRenderDataList();
  }
  return restored;
}

/* Lưu reportData của TẤT CẢ snapshot vào IDB — gọi sau mỗi lần archive */
async function idbSaveAllReportData() {
  const validKeys = new Set();
  for (const item of _archiveReportList) {
    const k = _idbKey(item);
    validKeys.add(k);
    if (item.reportData) {
      try { await _archIdbPut(k, item.reportData); } catch(e) { console.warn('[IDB] put failed:', e); }
    }
  }
  // Dọn dẹp orphan keys (snapshot đã xóa)
  try {
    const allKeys = await _archIdbGetAllKeys();
    for (const k of allKeys) {
      if (!validKeys.has(k)) await _archIdbDelete(k).catch(() => {});
    }
  } catch(e) {}
}

/* Khôi phục reportData từ IDB vào _archiveReportList sau khi load metadata */
async function idbRestoreAllReportData() {
  let restored = 0;
  for (const item of _archiveReportList) {
    if (item.reportData && Array.isArray(item.reportData)) continue; // đã có
    try {
      const data = await _archIdbGet(_idbKey(item));
      if (Array.isArray(data) && data.length > 0) {
        item.reportData = data;
        restored++;
      }
    } catch(e) {}
  }
  if (restored > 0) {
    (0)&&console.log(`[IDB] ✅ Khôi phục reportData cho ${restored}/${_archiveReportList.length} snapshot`);
    archiveRenderReportList(); // cập nhật badge ✅/⚠
  }
  return restored;
}

function archiveSaveToStorage() {
  // localStorage: metadata only (không có reportData — tránh quota 5MB)
  try {
    const dataMeta   = _archiveDataList.map(({ data, ...rest }) => rest);
    const reportMeta = _archiveReportList.map(({ reportData, ...rest }) => rest);
    localStorage.setItem('_archiveDataList',   JSON.stringify(dataMeta));
    localStorage.setItem('_archiveReportList', JSON.stringify(reportMeta));
  } catch (e) {
    console.warn('⚠️ LocalStorage save failed:', e);
  }
  // IndexedDB: toàn bộ reportData VÀ data — bền vững, không giới hạn dung lượng
  idbSaveAllReportData().catch(e => console.warn('[IDB] saveReports failed:', e));
  idbSaveAllDataItems().catch(e => console.warn('[IDB] saveDataItems failed:', e));
}

function archiveLoadFromStorage() {
  try {
    _archiveDataList   = JSON.parse(localStorage.getItem('_archiveDataList')   || '[]');
    _archiveReportList = JSON.parse(localStorage.getItem('_archiveReportList') || '[]');
    window._archiveReportList = _archiveReportList;
    // 🚀 Nếu archive trống → nạp _PRE_SNAPS vào bộ nhớ ngay lập tức (đồng bộ)
    if (_archiveReportList.length === 0 && window._PRE_SNAPS && window._PRE_SNAPS.length > 0) {
      window._PRE_SNAPS.forEach(function(s) {
        _archiveReportList.push(Object.assign({}, s.meta, {reportData: s.rd}));
      });
      var metaOnly = _archiveReportList.map(function(r){var m=Object.assign({},r);delete m.reportData;return m;});
      try{localStorage.setItem('_archiveReportList',JSON.stringify(metaOnly));}catch(e){}
      if (typeof idbSaveAllReportData === 'function') {
        idbSaveAllReportData().catch(function(e){console.warn('[PRE_SNAPS] IDB:',e);});
      }
      (0)&&console.log('[PRE_SNAPS] ✅ Loaded',_archiveReportList.length,'snapshots into archive');
      window._PRE_SNAPS = null;
    }

    // ✅ Migration 1: Đổi tên dd.mm.yyyy → dd/mm/yyyy
    const normDotDate = s => s ? s.replace(/\b(\d{1,2})\.(\d{1,2})\.(\d{4})\b/g, (_, d, m, y) =>
      `${d.padStart(2,'0')}/${m.padStart(2,'0')}/${y}`) : s;
    let migrated = false;
    _archiveDataList.forEach(item => {
      const fixed = normDotDate(item.name);
      if (fixed !== item.name) { item.name = fixed; migrated = true; }
    });
    _archiveReportList.forEach(item => {
      const fixed = normDotDate(item.name);
      if (fixed !== item.name) { item.name = fixed; migrated = true; }
    });

    // ✅ Migration 2: kind:'year' → 'year_end'
    _archiveReportList.forEach(item => {
      if (item.tag && item.tag.kind === 'year') {
        item.tag = { kind: 'year_end', year: item.tag.year - 1 };
        migrated = true;
      }
    });

    // ✅ Migration 3: Auto-detect tag cho snapshot chưa có tag
    _archiveReportList.forEach(item => {
      if (item.tag !== undefined) return;
      let detected = null;
      const m = String(item.name || '').match(/\b(\d{1,2})\/(\d{1,2})\/(\d{4})\b/);
      if (m) {
        detected = archiveDetectTag(`${m[1].padStart(2,'0')}/${m[2].padStart(2,'0')}/${m[3]}`, null);
      }
      if (!detected && item.timestamp) {
        const t = archiveDetectTag(null, new Date(item.timestamp));
        if (t && t.kind !== 'other') detected = t;
      }
      item.tag = detected || null;
      migrated = true;
    });

    // Lưu lại nếu có migration (KHÔNG gọi idbSaveAllReportData ở đây vì reportData chưa load)
    if (migrated) {
      try {
        const dataMeta   = _archiveDataList.map(({ data, ...rest }) => rest);
        const reportMeta = _archiveReportList.map(({ reportData, ...rest }) => rest);
        localStorage.setItem('_archiveDataList',   JSON.stringify(dataMeta));
        localStorage.setItem('_archiveReportList', JSON.stringify(reportMeta));
      } catch(e) {}
    }

    // ⚡ Khôi phục reportData từ IndexedDB (async — không block UI)
    idbRestoreAllReportData().catch(e => console.warn('[IDB] restore reports failed:', e));
    // ⚡ Khôi phục data từ IndexedDB — FIX: trước đây bị bỏ quên, gây mất data khi reload
    idbRestoreAllDataItems().catch(e => console.warn('[IDB] restore data failed:', e));

  } catch (e) {
    console.warn('⚠️ Failed to load archives:', e);
    _archiveDataList   = [];
    _archiveReportList = [];
    window._archiveReportList = _archiveReportList;
  }
}

