/* ═══════════════════════════════════════════════════════════════════════
   📊 SO SÁNH 2 SNAPSHOT TỰ CHỌN
   ───────────────────────────────────────────────────────────────────────
   Mở modal cho user chọn 2 snapshot (A=cũ, B=mới hoặc DATA hiện tại)
   → render bảng so sánh chi tiết theo CBTD và phòng.
   ═══════════════════════════════════════════════════════════════════════ */
function archiveComparisons() {
  if (_archiveReportList.length < 1) {
    alert('Cần có ít nhất 1 snapshot trong Lưu trữ Báo cáo để so sánh.\nVào QLTD → Archive Report để tạo snapshot.');
    return;
  }
  archiveOpenCompareModal();
}

function archiveOpenCompareModal() {
  let modal = document.getElementById('modal-archive-compare');
  if (!modal) {
    modal = document.createElement('div');
    modal.className = 'modal-overlay';
    modal.id = 'modal-archive-compare';
    modal.style.display = 'none';
    modal.onclick = (e) => { if (e.target === modal) archiveCloseCompareModal(); };
    modal.innerHTML = `
      <div class="modal" style="max-width:1100px;max-height:92vh">
        <div class="modal-header" style="background:linear-gradient(135deg,#1e40af,#3b82f6)">
          <h2 style="color:#fff">📊 So sánh 2 snapshot báo cáo</h2>
          <button class="modal-close" onclick="archiveCloseCompareModal()" style="color:#fff;opacity:.9">✕</button>
        </div>
        <div class="modal-body" style="padding:0;max-height:calc(92vh - 70px);overflow-y:auto">
          <div style="padding:14px 18px;background:#eef5ff;border-bottom:1px solid #c7d8ed;display:flex;gap:12px;flex-wrap:wrap;align-items:end">
            <div style="flex:1;min-width:240px">
              <label style="font-size:11px;font-weight:700;color:#1e40af;display:block;margin-bottom:4px">📌 Snapshot A (mốc cũ)</label>
              <select id="cmp-snap-a" onchange="archiveRenderCompareResult()" style="width:100%;padding:7px 10px;border:1.5px solid #93c5fd;border-radius:6px;font-size:12px;background:#fff"></select>
            </div>
            <div style="font-size:18px;color:#1e40af;font-weight:700;margin:0 4px;align-self:center;padding-bottom:4px">vs</div>
            <div style="flex:1;min-width:240px">
              <label style="font-size:11px;font-weight:700;color:#1e40af;display:block;margin-bottom:4px">📌 Snapshot B (mốc mới)</label>
              <select id="cmp-snap-b" onchange="archiveRenderCompareResult()" style="width:100%;padding:7px 10px;border:1.5px solid #93c5fd;border-radius:6px;font-size:12px;background:#fff"></select>
            </div>
            <button class="btn btn-blue btn-sm" onclick="archiveSwapSnapshots()" title="Đổi vị trí A và B">🔄 Hoán đổi</button>
          </div>
          <div id="cmp-result" style="padding:14px 18px"></div>
        </div>
      </div>`;
    document.body.appendChild(modal);
  }

  // Populate dropdowns
  const optionsHtml = (selectedIdx) => {
    let opts = '';
    _archiveReportList.forEach((s, i) => {
      const tagLbl = (typeof archiveTagLabel === 'function') ? archiveTagLabel(s.tag) : '';
      opts += `<option value="snap-${i}" ${selectedIdx === `snap-${i}` ? 'selected' : ''}>${escapeHtml(s.name)} ${tagLbl ? '— ' + tagLbl : ''}</option>`;
    });
    opts += `<option value="current" ${selectedIdx === 'current' ? 'selected' : ''}>📊 DATA HIỆN TẠI (DATA.qltd)</option>`;
    return opts;
  };

  // Default: A = oldest snapshot, B = current data
  const aSel = document.getElementById('cmp-snap-a');
  const bSel = document.getElementById('cmp-snap-b');
  aSel.innerHTML = optionsHtml('snap-0');
  bSel.innerHTML = optionsHtml('current');

  modal.style.display = 'flex';
  archiveRenderCompareResult();
}

function archiveCloseCompareModal() {
  const m = document.getElementById('modal-archive-compare');
  if (m) m.style.display = 'none';
}

function archiveSwapSnapshots() {
  const a = document.getElementById('cmp-snap-a');
  const b = document.getElementById('cmp-snap-b');
  if (!a || !b) return;
  const tmp = a.value;
  a.value = b.value;
  b.value = tmp;
  archiveRenderCompareResult();
}

function archiveGetSnapByValue(val) {
  if (val === 'current') {
    return {
      name: '📊 DATA hiện tại',
      date: new Date().toLocaleString('vi-VN'),
      reportData: DATA?.qltd || [],
      _isCurrent: true
    };
  }
  const m = String(val).match(/^snap-(\d+)$/);
  if (!m) return null;
  return _archiveReportList[+m[1]] || null;
}

function archiveRenderCompareResult() {
  const el = document.getElementById('cmp-result');
  if (!el) return;
  const aVal = document.getElementById('cmp-snap-a')?.value;
  const bVal = document.getElementById('cmp-snap-b')?.value;
  const A = archiveGetSnapByValue(aVal);
  const B = archiveGetSnapByValue(bVal);
  if (!A || !B) { el.innerHTML = '<p style="color:var(--gray-500);text-align:center;padding:30px">Chọn 2 snapshot để so sánh</p>'; return; }
  if (aVal === bVal) {
    el.innerHTML = '<p style="color:var(--orange);text-align:center;padding:30px">⚠ Hai snapshot trùng nhau. Chọn 2 mốc khác nhau.</p>';
    return;
  }

  const aRows = A.reportData || [];
  const bRows = B.reportData || [];

  // Tổng quan
  const sumDN = rows => rows.reduce((s, r) => s + (Number(r[11]) || 0), 0);
  const countKH = rows => new Set(rows.map(r => r[0]).filter(Boolean)).size;
  const fnNH  = (typeof isNganHan  === 'function') ? isNganHan  : v => /ngắn|thấu/i.test(v||'');
  const fnTDH = (typeof isTrungHan === 'function') ? isTrungHan : v => /trung|dài/i.test(v||'');
  const sumByType = (rows, fn) => rows.filter(r => fn(r[13])).reduce((s, r) => s + (Number(r[11]) || 0), 0);

  const aDN = sumDN(aRows), bDN = sumDN(bRows);
  const aKH = countKH(aRows), bKH = countKH(bRows);
  const aNH = sumByType(aRows, fnNH), bNH = sumByType(bRows, fnNH);
  const aTDH = sumByType(aRows, fnTDH), bTDH = sumByType(bRows, fnTDH);

  const fmt = n => (typeof bckhFmtMoney === 'function') ? bckhFmtMoney(n) : Math.round(n).toLocaleString('vi-VN');
  const fmtSign = (delta, base) => {
    const pct = base ? (delta / base) * 100 : 0;
    const sign = delta > 0 ? '+' : (delta < 0 ? '−' : '');
    const color = delta > 0 ? '#15803d' : (delta < 0 ? '#b91c1c' : '#6b7280');
    const arrow = delta > 0 ? 'Tăng' : (delta < 0 ? 'Giảm' : '─');
    return `<span style="color:${color};font-weight:700">${arrow} ${sign}${fmt(Math.abs(delta))}${base ? ` (${pct >= 0 ? '+' : ''}${pct.toFixed(1)}%)` : ''}</span>`;
  };

  // Stat cards
  const statRow = `
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px;margin-bottom:14px">
      ${[
        ['💰 Tổng dư nợ', aDN, bDN, fmt],
        ['📊 Dư nợ ngắn hạn', aNH, bNH, fmt],
        ['🏠 Dư nợ trung-dài hạn', aTDH, bTDH, fmt],
        ['👥 Số khách hàng', aKH, bKH, n => Math.round(n).toLocaleString('vi-VN')]
      ].map(([lbl, av, bv, f]) => `
        <div style="background:#fff;border:1px solid var(--gray-200);border-radius:8px;padding:10px 12px">
          <div style="font-size:10px;font-weight:700;color:var(--gray-500);text-transform:uppercase;letter-spacing:.4px;margin-bottom:4px">${lbl}</div>
          <div style="display:flex;justify-content:space-between;align-items:baseline;gap:10px">
            <div><div style="font-size:9px;color:var(--gray-400)">A</div><div style="font-weight:700;color:var(--navy)">${f(av)}</div></div>
            <div style="font-size:14px;color:var(--gray-300)">→</div>
            <div style="text-align:right"><div style="font-size:9px;color:var(--gray-400)">B</div><div style="font-weight:700;color:var(--navy)">${f(bv)}</div></div>
          </div>
          <div style="font-size:11px;text-align:center;margin-top:6px;border-top:1px dashed var(--gray-200);padding-top:5px">
            ${fmtSign(bv - av, av)}
          </div>
        </div>`).join('')}
    </div>`;

  // CBTD breakdown
  const aByCB = {}, bByCB = {};
  for (const r of aRows) {
    const cb = String(r[12] || '').trim() || '(N/A)';
    aByCB[cb] = (aByCB[cb] || 0) + (Number(r[11]) || 0);
  }
  for (const r of bRows) {
    const cb = String(r[12] || '').trim() || '(N/A)';
    bByCB[cb] = (bByCB[cb] || 0) + (Number(r[11]) || 0);
  }
  const allCBs = [...new Set([...Object.keys(aByCB), ...Object.keys(bByCB)])]
    .map(name => ({ name, a: aByCB[name] || 0, b: bByCB[name] || 0, delta: (bByCB[name] || 0) - (aByCB[name] || 0) }))
    .sort((x, y) => Math.abs(y.delta) - Math.abs(x.delta));

  const cbRows = allCBs.map((x, i) => {
    const pct = x.a ? (x.delta / x.a) * 100 : 0;
    const color = x.delta > 0 ? '#15803d' : (x.delta < 0 ? '#b91c1c' : '#6b7280');
    return `
      <tr style="border-top:1px solid var(--gray-200);${i % 2 === 0 ? '' : 'background:var(--gray-50)'}">
        <td style="padding:5px 8px;color:var(--gray-500)">${i + 1}</td>
        <td style="padding:5px 8px;font-weight:600;color:var(--navy)">${escapeHtml(x.name)}</td>
        <td style="padding:5px 8px;text-align:right;color:var(--gray-700)">${fmt(x.a)}</td>
        <td style="padding:5px 8px;text-align:right;color:var(--gray-700)">${fmt(x.b)}</td>
        <td style="padding:5px 8px;text-align:right;color:${color};font-weight:700">${x.delta > 0 ? '+' : ''}${fmt(x.delta)}</td>
        <td style="padding:5px 8px;text-align:right;color:${color};font-weight:600">${x.a ? `${pct >= 0 ? '+' : ''}${pct.toFixed(1)}%` : '—'}</td>
      </tr>`;
  }).join('');

  el.innerHTML = `
    <div style="display:flex;gap:8px;flex-wrap:wrap;font-size:11px;margin-bottom:12px">
      <span style="background:#dbeafe;color:#1e40af;padding:4px 10px;border-radius:5px"><strong>A:</strong> ${escapeHtml(A.name)} <span style="opacity:.7">(${A.date})</span></span>
      <span style="font-size:14px;color:var(--gray-400);align-self:center">→</span>
      <span style="background:#dcfce7;color:#15803d;padding:4px 10px;border-radius:5px"><strong>B:</strong> ${escapeHtml(B.name)} <span style="opacity:.7">(${B.date})</span></span>
    </div>

    ${statRow}

    <h4 style="margin:14px 0 8px;color:var(--navy);font-size:13px">📋 So sánh chi tiết theo CBTD</h4>
    <div style="border:1px solid var(--gray-200);border-radius:6px;overflow:hidden">
      <table style="width:100%;border-collapse:collapse;font-size:11px">
        <thead style="background:var(--navy);color:#fff">
          <tr>
            <th style="padding:6px 8px;text-align:left;width:40px">#</th>
            <th style="padding:6px 8px;text-align:left">CBTD</th>
            <th style="padding:6px 8px;text-align:right;width:120px">A (cũ)</th>
            <th style="padding:6px 8px;text-align:right;width:120px">B (mới)</th>
            <th style="padding:6px 8px;text-align:right;width:120px">Biến động</th>
            <th style="padding:6px 8px;text-align:right;width:80px">%</th>
          </tr>
        </thead>
        <tbody>${cbRows || `<tr><td colspan="6" style="padding:30px;text-align:center;color:var(--gray-500)">Không có dữ liệu CBTD để so sánh</td></tr>`}</tbody>
      </table>
    </div>

    ${archiveRenderCustomerChanges(aRows, bRows)}
  `;
}

// QA-FEATURE: phan tich chi tiet KH moi / da tat toan / doi nhom no giua 2 moc so sanh
function archiveRenderCustomerChanges(aRows, bRows) {
  const aMap = new Map(), bMap = new Map();
  aRows.forEach(r => { const ma = String(r[0]||'').trim(); if (ma && !aMap.has(ma)) aMap.set(ma, r); });
  bRows.forEach(r => { const ma = String(r[0]||'').trim(); if (ma && !bMap.has(ma)) bMap.set(ma, r); });

  const newCust = [], closedCust = [], groupWorse = [], groupBetter = [];
  const nhomNum = s => { const m = String(s||'').match(/\d/); return m ? +m[0] : 0; };

  bMap.forEach((r, ma) => { if (!aMap.has(ma)) newCust.push(r); });
  aMap.forEach((r, ma) => { if (!bMap.has(ma)) closedCust.push(r); });
  aMap.forEach((rA, ma) => {
    const rB = bMap.get(ma);
    if (!rB) return;
    const nA = nhomNum(rA[18]), nB = nhomNum(rB[18]);
    if (nA && nB && nA !== nB) {
      const item = { ma, ten: rB[1]||rA[1], nA: rA[18], nB: rB[18] };
      if (nB > nA) groupWorse.push(item); else groupBetter.push(item);
    }
  });
  groupWorse.sort((x,y) => (nhomNum(y.nB)-nhomNum(y.nA)) - (nhomNum(x.nB)-nhomNum(x.nA)));

  const fmtM = n => (typeof bckhFmtMoney === 'function') ? bckhFmtMoney(n) : Math.round(n).toLocaleString('vi-VN');
  const listBlock = (title, items, color, bg, rowFn, emptyTxt) => `
    <details style="margin-top:10px;border:1px solid ${color}44;border-radius:8px;overflow:hidden">
      <summary style="cursor:pointer;padding:9px 12px;background:${bg};color:${color};font-weight:700;font-size:12px">${title} (${items.length})</summary>
      <div style="max-height:280px;overflow-y:auto">
        ${items.length ? `<table style="width:100%;border-collapse:collapse;font-size:11px">${items.map(rowFn).join('')}</table>`
                        : `<div style="padding:14px;text-align:center;color:var(--gray-500)">${emptyTxt}</div>`}
      </div>
    </details>`;

  return `
    <h4 style="margin:16px 0 4px;color:var(--navy);font-size:13px">🔍 Biến động khách hàng chi tiết (theo mã KH)</h4>
    ${listBlock('🆕 Khách hàng mới xuất hiện', newCust, '#15803d', '#dcfce7',
      r => `<tr style="border-top:1px solid #e5e7eb"><td style="padding:5px 8px;font-weight:600">${escapeHtml(String(r[1]||''))}</td><td style="padding:5px 8px;color:var(--gray-500)">${escapeHtml(String(r[0]||''))}</td><td style="padding:5px 8px;text-align:right;color:#15803d;font-weight:700">${fmtM(Number(r[11])||0)}</td></tr>`,
      'Không có khách hàng mới trong kỳ này.')}
    ${listBlock('📕 Khách hàng đã tất toán / không còn dư nợ', closedCust, '#b91c1c', '#fde8e6',
      r => `<tr style="border-top:1px solid #e5e7eb"><td style="padding:5px 8px;font-weight:600">${escapeHtml(String(r[1]||''))}</td><td style="padding:5px 8px;color:var(--gray-500)">${escapeHtml(String(r[0]||''))}</td><td style="padding:5px 8px;text-align:right;color:var(--gray-500)">${fmtM(Number(r[11])||0)} (mốc A)</td></tr>`,
      'Không có khách hàng tất toán trong kỳ này.')}
    ${listBlock('⚠ Nhảy nhóm nợ XẤU HƠN — cần chú ý', groupWorse, '#b45309', '#fef3e2',
      x => `<tr style="border-top:1px solid #e5e7eb"><td style="padding:5px 8px;font-weight:600">${escapeHtml(x.ten)}</td><td style="padding:5px 8px;color:var(--gray-500)">${escapeHtml(x.ma)}</td><td style="padding:5px 8px;text-align:right"><span style="color:var(--gray-500)">${escapeHtml(x.nA)}</span> → <span style="color:#b45309;font-weight:700">${escapeHtml(x.nB)}</span></td></tr>`,
      'Không có khách hàng nào nhảy nhóm nợ xấu hơn — tốt.')}
    ${listBlock('✅ Cải thiện nhóm nợ (tốt lên)', groupBetter, '#15803d', '#dcfce7',
      x => `<tr style="border-top:1px solid #e5e7eb"><td style="padding:5px 8px;font-weight:600">${escapeHtml(x.ten)}</td><td style="padding:5px 8px;color:var(--gray-500)">${escapeHtml(x.ma)}</td><td style="padding:5px 8px;text-align:right"><span style="color:var(--gray-500)">${escapeHtml(x.nA)}</span> → <span style="color:#15803d;font-weight:700">${escapeHtml(x.nB)}</span></td></tr>`,
      'Chưa có khách hàng nào cải thiện nhóm nợ giữa 2 mốc.')}
  `;
}

// Initialize on load
archiveInit();

/* ═══════════════════════════════════════════════════════════════
   AUTO-SYNC ENGINE — PRO-38
   Tự động đọc file IPCAS từ folder máy tính theo lịch định sẵn
   Sử dụng File System Access API (Chrome/Edge 86+)
   ═══════════════════════════════════════════════════════════════ */

const AUTOSYNC_STORAGE_KEY = '_autoSyncConfig';

// State
let _asFileHandle   = null;   // FileSystemFileHandle
let _asIntervalMin  = 10;
let _asEnabled      = false;
let _asTimerID      = null;
let _asCountdownID  = null;
let _asNextSync     = null;
let _asLastModified = null;
let _asSmartCheck   = true;
let _asAction       = 'ask';
let _asLogLines     = [];

/* ── Mở modal ────────────────────────────────────────────── */
function openAutoSyncModal() {
  autoSyncLoadConfig();
  autoSyncRenderModal();
  // Try compat with both openModal patterns
  const modal = document.getElementById('modal-autosync');
  if (modal) {
    modal.classList.add('open');
    modal.style.display = 'flex';
  }
}

function closeAutoSyncModal() {
  const modal = document.getElementById('modal-autosync');
  if (modal) {
    modal.classList.remove('open');
    modal.style.display = 'none';
  }
}

/* ── LocalStorage config ─────────────────────────────────── */
function autoSyncSaveConfig() {
  try {
    localStorage.setItem(AUTOSYNC_STORAGE_KEY, JSON.stringify({
      intervalMin: _asIntervalMin,
      enabled: _asEnabled,
      smartCheck: _asSmartCheck,
      action: _asAction,
      lastModified: _asLastModified,
      logLines: _asLogLines.slice(-60),
    }));
  } catch(e) {}
}
function autoSyncLoadConfig() {
  try {
    const raw = localStorage.getItem(AUTOSYNC_STORAGE_KEY);
    if (!raw) return;
    const cfg = JSON.parse(raw);
    _asIntervalMin  = cfg.intervalMin  || 10;
    _asEnabled      = cfg.enabled      || false;
    _asSmartCheck   = cfg.smartCheck   !== false;
    _asAction       = cfg.action       || 'ask';
    _asLastModified = cfg.lastModified || null;
    _asLogLines     = cfg.logLines     || [];
  } catch(e) {}
}

/* ── Render modal ────────────────────────────────────────── */
function autoSyncRenderModal() {
  document.querySelectorAll('.autosync-interval-btn').forEach(btn => {
    btn.classList.toggle('selected', +btn.dataset.min === _asIntervalMin);
  });
  const sc = document.getElementById('autosync-smart');
  if (sc) sc.checked = _asSmartCheck;
  const ar = document.querySelector(`input[name="autosync-action"][value="${_asAction}"]`);
  if (ar) ar.checked = true;
  const tog = document.getElementById('autosync-toggle');
  if (tog) tog.checked = _asEnabled;
  if (_asFileHandle) {
    document.getElementById('autosync-file-name').textContent = '📄 ' + _asFileHandle.name;
    document.getElementById('autosync-file-meta').textContent = 'File đã chọn — hệ thống có quyền đọc';
    document.getElementById('autosync-file-picker').style.borderColor = 'var(--green-main)';
    document.getElementById('autosync-file-picker').style.background  = 'var(--green-pale)';
  }
  autoSyncUpdateStatusUI();
  autoSyncRenderLog();
}

function autoSyncUpdateStatusUI() {
  const dot  = document.getElementById('autosync-dot');
  const txt  = document.getElementById('autosync-status-text');
  const cdn  = document.getElementById('autosync-countdown');
  const last = document.getElementById('autosync-last-sync');
  const topStatus    = document.getElementById('autosync-status');
  const topBadge     = document.getElementById('autosync-badge');
  const sidebarBadge = document.getElementById('badge-autosync');
  const btnSync      = document.getElementById('btn-autosync');

  if (!dot) return;

  if (_asEnabled && _asFileHandle) {
    dot.className = 'autosync-status-dot active';
    txt.textContent = `🔄 Đang chạy — mỗi ${_asIntervalMin} phút · ${_asFileHandle.name}`;
    if (cdn) cdn.style.display = 'block';
    if (topStatus)    topStatus.style.display    = 'inline';
    if (topBadge)     topBadge.style.display     = 'block';
    if (sidebarBadge) sidebarBadge.style.display = 'inline-flex';
    if (btnSync) btnSync.style.background = 'var(--green-dark)';
  } else if (_asEnabled && !_asFileHandle) {
    dot.className = 'autosync-status-dot error';
    txt.textContent = '⚠️ Bật nhưng chưa chọn file nguồn';
    if (topStatus)    { topStatus.textContent = '⚠️ Chưa chọn file'; topStatus.style.display = 'inline'; }
    if (topBadge)     topBadge.style.display = 'block';
    if (sidebarBadge) sidebarBadge.style.display = 'inline-flex';
  } else {
    dot.className = 'autosync-status-dot';
    txt.textContent = 'Chưa bật Auto-Sync';
    if (cdn)          cdn.style.display          = 'none';
    if (topStatus)    topStatus.style.display    = 'none';
    if (topBadge)     topBadge.style.display     = 'none';
    if (sidebarBadge) sidebarBadge.style.display = 'none';
    if (btnSync) btnSync.style.background = 'var(--navy-mid)';
  }
  if (last && _asLastModified) {
    const d = new Date(_asLastModified);
    last.textContent = 'File: ' + d.toLocaleString('vi-VN', { hour:'2-digit', minute:'2-digit', day:'2-digit', month:'2-digit' });
  }
}

/* ── Chọn file (File System Access API) ─────────────────── */
async function autoSyncPickFile() {
  if (!window.showOpenFilePicker) {
    alert('⚠️ Tính năng này yêu cầu Chrome hoặc Edge phiên bản 86 trở lên.\nVui lòng cập nhật trình duyệt và thử lại.');
    return;
  }
  try {
    const [handle] = await window.showOpenFilePicker({
      types: [{
        description: 'File IPCAS (Excel / CSV)',
        accept: {
          'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': ['.xlsx', '.xlsm'],
          'application/vnd.ms-excel': ['.xls'],
          'text/csv': ['.csv'],
        }
      }],
      multiple: false,
    });
    _asFileHandle = handle;
    document.getElementById('autosync-file-name').textContent = '📄 ' + handle.name;
    document.getElementById('autosync-file-meta').textContent = 'Đã cấp quyền đọc — sẵn sàng sync';
    document.getElementById('autosync-file-picker').style.borderColor = 'var(--green-main)';
    document.getElementById('autosync-file-picker').style.background  = 'var(--green-pale)';
    autoSyncLog('info', 'Đã chọn file: ' + handle.name);
    autoSyncUpdateStatusUI();
    autoSyncSaveConfig();
    if (_asEnabled) { autoSyncStop(); autoSyncStart(); }
  } catch(e) {
    if (e.name !== 'AbortError') autoSyncLog('err', 'Lỗi chọn file: ' + e.message);
  }
}

/* ── Chu kỳ ─────────────────────────────────────────────── */
function autoSyncSelectInterval(min) {
  _asIntervalMin = min;
  document.querySelectorAll('.autosync-interval-btn').forEach(btn => {
    btn.classList.toggle('selected', +btn.dataset.min === min);
  });
  autoSyncSaveConfig();
  if (_asEnabled) { autoSyncStop(); autoSyncStart(); }
}

/* ── Bật / Tắt ──────────────────────────────────────────── */
function autoSyncToggle(enabled) {
  const sc = document.getElementById('autosync-smart');
  const ar = document.querySelector('input[name="autosync-action"]:checked');
  if (sc) _asSmartCheck = sc.checked;
  if (ar) _asAction     = ar.value;
  _asEnabled = enabled;
  autoSyncSaveConfig();
  if (enabled) {
    if (!_asFileHandle) {
      autoSyncLog('warn', 'Chưa chọn file — vui lòng chọn file nguồn trước');
      autoSyncUpdateStatusUI();
      return;
    }
    autoSyncStart();
    autoSyncLog('ok', `Auto-Sync BẬT — chu kỳ ${_asIntervalMin} phút · hành động: ${_asAction}`);
  } else {
    autoSyncStop();
    autoSyncLog('info', 'Auto-Sync ĐÃ TẮT');
  }
  autoSyncUpdateStatusUI();
  autoSyncRenderLog();
}

/* ── Timer ───────────────────────────────────────────────── */
function autoSyncStart() {
  autoSyncStop();
  const ms = _asIntervalMin * 60 * 1000;
  _asNextSync   = new Date(Date.now() + ms);
  _asTimerID    = setInterval(autoSyncRun, ms);
  _asCountdownID= setInterval(autoSyncTickCountdown, 1000);
  autoSyncTickCountdown();
}
function autoSyncStop() {
  if (_asTimerID)     { clearInterval(_asTimerID);     _asTimerID = null; }
  if (_asCountdownID) { clearInterval(_asCountdownID); _asCountdownID = null; }
  _asNextSync = null;
  const cdn = document.getElementById('autosync-countdown');
  if (cdn) cdn.style.display = 'none';
  const ts = document.getElementById('autosync-status');
  if (ts) ts.style.display = 'none';
}
function autoSyncTickCountdown() {
  if (!_asNextSync) return;
  const diff = _asNextSync - Date.now();
  if (diff < 0) return;
  const m = Math.floor(diff / 60000);
  const s = Math.floor((diff % 60000) / 1000);
  const label = `⏱ Sync tiếp: ${m > 0 ? m + ' phút ' : ''}${String(s).padStart(2,'0')} giây`;
  const cdn = document.getElementById('autosync-countdown');
  if (cdn) { cdn.textContent = label; cdn.style.display = 'block'; }
  const ts = document.getElementById('autosync-status');
  if (ts && ts.style.display !== 'none') ts.textContent = label;
}

/* ── Thực hiện sync ─────────────────────────────────────── */
async function autoSyncRun() {
  if (!_asFileHandle) { autoSyncLog('warn', 'Không có file handle — bỏ qua'); return; }
  _asNextSync = new Date(Date.now() + _asIntervalMin * 60 * 1000);

  try {
    // Kiểm tra / xin lại quyền
    const perm = await _asFileHandle.queryPermission({ mode: 'read' });
    if (perm !== 'granted') {
      const req = await _asFileHandle.requestPermission({ mode: 'read' });
      if (req !== 'granted') {
        autoSyncLog('err', 'Không có quyền đọc file — user từ chối');
        showToast('⚠️ Auto-Sync cần quyền đọc file — mở modal để xác nhận lại', 'red');
        return;
      }
    }

    const file = await _asFileHandle.getFile();
    const modTime = file.lastModified;

    // Smart check
    if (_asSmartCheck && _asLastModified && modTime === _asLastModified) {
      autoSyncLog('info', `[${asFmtNow()}] File chưa thay đổi — bỏ qua`);
      return;
    }

    autoSyncLog('ok', `[${asFmtNow()}] File mới/cập nhật: ${file.name} (${(file.size/1024).toFixed(0)} KB)`);
    _asLastModified = modTime;
    autoSyncSaveConfig();
    autoSyncUpdateStatusUI();

    if (_asAction === 'notify') {
      showToast(`🔄 File IPCAS thay đổi lúc ${asFmtNow()} — mở "Nhập IPCAS" để import`, 'gold');
      return;
    }

    // Parse — uses existing parsers from main app
    let rows;
    const fn = file.name.toLowerCase();
    if (fn.endsWith('.csv'))                    rows = parseCSV(await file.text());
    else if (/\.(xlsx|xlsm)$/.test(fn))         rows = await parseXLSX(file);
    else if (/\.xls$/.test(fn))                 rows = await parseXLS_legacy(file);
    else { autoSyncLog('err', 'Định dạng không hỗ trợ: ' + file.name); return; }

    if (!rows || rows.length < 2) { autoSyncLog('err', 'File rỗng hoặc thiếu dữ liệu'); return; }

    const transformed = transformIPCAS(rows);

    autoSyncLog('ok', `Parsed: ${rows.length} dòng gốc → ${transformed.length} bản ghi hợp lệ`);

    if (_asAction === 'ask') {
      pendingImportRows = transformed;
      closeAutoSyncModal();
      const fInfo = document.getElementById('import-file-info');
      const fPrev = document.getElementById('import-preview');
      const fSync = document.getElementById('import-sync-panel');
      const fBtn  = document.getElementById('btn-do-import');
      if (fInfo) fInfo.textContent = `🔄 Auto-Sync: ${file.name}`;
      if (fPrev) fPrev.style.display = 'block';
      if (fSync) fSync.style.display = 'none';
      if (typeof previewImport === 'function') previewImport(transformed);
      if (fBtn) {
        fBtn.disabled = false;
        fBtn.style.opacity = '1';
        fBtn.textContent = `✅ Xác nhận nhập (${transformed.length} bản ghi)`;
      }
      if (typeof openModal === 'function') openModal('modal-import');
      else {
        const mi = document.getElementById('modal-import');
        if (mi) { mi.classList.add('open'); mi.style.display = 'flex'; }
      }
      showToast(`🔄 Auto-Sync phát hiện file mới — vui lòng xác nhận nhập`, 'gold');

    } else if (_asAction === 'auto') {
      const keep = transformed.filter(r => (Number(r[11]) || 0) > 0);
      if (!keep.length) { autoSyncLog('warn', 'Không có bản ghi dư nợ > 0 — bỏ qua'); return; }
      DATA.qltd = keep;
      saveData();
      rebuildAll();
      autoSyncLog('ok', `✅ Tự động import ${keep.length} bản ghi (loại ${transformed.length - keep.length} dư nợ = 0)`);
      showToast(`✅ Auto-Sync xong: ${keep.length} bản ghi lúc ${asFmtNow()}`, 'green');
    }

  } catch(e) {
    autoSyncLog('err', `Lỗi sync: ${e.message}`);
    console.error('[AutoSync]', e);
  }
}

/* ── Sync thủ công ──────────────────────────────────────── */
async function autoSyncRunNow() {
  if (!_asFileHandle) { alert('⚠️ Chưa chọn file nguồn'); return; }
  const sc = document.getElementById('autosync-smart');
  const ar = document.querySelector('input[name="autosync-action"]:checked');
  if (sc) _asSmartCheck = sc.checked;
  if (ar) _asAction     = ar.value;
  const origLM    = _asLastModified;
  _asLastModified = null;           // force check
  autoSyncLog('info', `▶️ Sync thủ công lúc ${asFmtNow()}...`);
  await autoSyncRun();
  if (!_asEnabled) _asLastModified = origLM;
  autoSyncRenderLog();
}

/* ── Xóa cài đặt ────────────────────────────────────────── */
function autoSyncClear() {
  if (!confirm('Xóa toàn bộ cài đặt Auto-Sync?')) return;
  autoSyncStop();
  _asFileHandle = null; _asEnabled = false; _asIntervalMin = 10;
  _asSmartCheck = true; _asAction = 'ask'; _asLastModified = null; _asLogLines = [];
  localStorage.removeItem(AUTOSYNC_STORAGE_KEY);
  autoSyncRenderModal();
  showToast('🗑️ Đã xóa cài đặt Auto-Sync', 'red');
}

/* ── Log ────────────────────────────────────────────────── */
function autoSyncLog(type, msg) {
  _asLogLines.push({ type, msg });
  if (_asLogLines.length > 100) _asLogLines = _asLogLines.slice(-80);
  autoSyncSaveConfig();
  autoSyncRenderLog();
}
function autoSyncRenderLog() {
  const el = document.getElementById('autosync-log');
  if (!el) return;
  if (!_asLogLines.length) {
    el.innerHTML = '<div class="log-line info">[Hệ thống] Chưa có hoạt động nào...</div>';
    return;
  }
  // Use simple HTML escape (avoid name clash)
  const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  el.innerHTML = _asLogLines.slice().reverse().map(l =>
    `<div class="log-line ${l.type}">${esc(l.msg)}</div>`
  ).join('');
}
function asFmtNow() {
  return new Date().toLocaleTimeString('vi-VN', { hour:'2-digit', minute:'2-digit', second:'2-digit' });
}

/* ── Khởi động khi load trang ───────────────────────────── */
(function autoSyncInit() {
  autoSyncLoadConfig();
  // FileSystemFileHandle không persist qua localStorage/reload
  // → reset enabled, hiện reminder
  if (_asEnabled) {
    _asEnabled = false;
    autoSyncSaveConfig();
    setTimeout(() => {
      showToast('🔄 Auto-Sync đã cài đặt — mở lại để cấp quyền đọc file và bật lại', 'gold');
    }, 2500);
  }
  autoSyncUpdateStatusUI();
})();

/* ═══════════════════════════════════════════════════════════════
   AUTO-SYNC: DÒ TÌM FILE THEO NGÀY DD.MM.YYYY TRONG THƯ MỤC
   ═══════════════════════════════════════════════════════════════ */
async function autoSyncPickFolder() {
  if (!window.showDirectoryPicker) {
    alert('⚠️ Tính năng này yêu cầu Chrome hoặc Edge phiên bản 86 trở lên.\nVui lòng cập nhật trình duyệt và thử lại.');
    return;
  }
  try {
    const dirHandle = await window.showDirectoryPicker({ mode: 'read' });
    autoSyncLog('info', `📁 Đang quét thư mục: ${dirHandle.name}...`);

    const today = new Date();
    today.setHours(0, 0, 0, 0);
    // Pattern: DD.MM.YYYY hoặc DD/MM/YYYY trong tên file
    const datePattern = /(\d{1,2})[./](\d{1,2})[./](\d{4})/;
    const candidates = [];

    for await (const [name, handle] of dirHandle.entries()) {
      if (handle.kind !== 'file') continue;
      if (!/\.(xlsx|xlsm|xls|csv)$/i.test(name)) continue;
      const m = datePattern.exec(name);
      if (!m) continue;
      const dd = parseInt(m[1],10), mm = parseInt(m[2],10), yyyy = parseInt(m[3],10);
      if (mm < 1 || mm > 12 || dd < 1 || dd > 31 || yyyy < 2000 || yyyy > 2100) continue;
      const fileDate = new Date(yyyy, mm - 1, dd);
      if (isNaN(fileDate.getTime())) continue;
      const file = await handle.getFile();
      candidates.push({ name, handle, fileDate, lastModified: file.lastModified });
    }

    if (!candidates.length) {
      autoSyncLog('warn', '⚠️ Không tìm thấy file nào có định dạng ngày DD.MM.YYYY trong thư mục');
      showToast('⚠️ Không tìm thấy file .xlsx/.csv có ngày DD.MM.YYYY', 'gold');
      return;
    }

    // Sắp xếp: (1) ngày gần hôm nay nhất, (2) tie-break: mới sửa gần nhất
    candidates.sort((a, b) => {
      const diffA = Math.abs(a.fileDate - today);
      const diffB = Math.abs(b.fileDate - today);
      if (diffA !== diffB) return diffA - diffB;
      return b.lastModified - a.lastModified;
    });

    const best = candidates[0];
    const fmtDate = `${String(best.fileDate.getDate()).padStart(2,'0')}/${String(best.fileDate.getMonth()+1).padStart(2,'0')}/${best.fileDate.getFullYear()}`;
    _asFileHandle = best.handle;

    const nameEl = document.getElementById('autosync-file-name');
    const metaEl = document.getElementById('autosync-file-meta');
    const picker = document.getElementById('autosync-file-picker');
    if (nameEl) nameEl.textContent = '📄 ' + best.name;
    if (metaEl) metaEl.textContent = `Tìm tự động · Ngày file: ${fmtDate} · Sửa lần cuối: ${new Date(best.lastModified).toLocaleString('vi-VN', {day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})}`;
    if (picker) { picker.style.borderColor = 'var(--green-main)'; picker.style.background = 'var(--green-pale)'; }

    autoSyncLog('ok', `✅ Tìm được ${candidates.length} file — chọn: ${best.name} (ngày ${fmtDate})`);
    if (candidates.length > 1) {
      autoSyncLog('info', `ℹ️ Các file khác (gần ngày): ${candidates.slice(1, 4).map(c=>c.name).join(', ')}${candidates.length > 4 ? ` và ${candidates.length-4} file khác` : ''}`);
    }
    autoSyncUpdateStatusUI();
    autoSyncSaveConfig();
    if (_asEnabled) { autoSyncStop(); autoSyncStart(); }
  } catch(e) {
    if (e.name !== 'AbortError') autoSyncLog('err', 'Lỗi quét thư mục: ' + e.message);
  }
}

